(() => {
  'use strict';
  const lessons = window.GERMAN_LESSONS || [];
  const storageKey = 'ambertheory-german-studio-v1';
  const root = document.getElementById('app');
  const defaultState = () => ({completed:[],scores:{},drafts:{},submissions:[],reviews:{},assigned:true});
  const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const stored = (() => {try{return JSON.parse(localStorage.getItem(storageKey));}catch{return null;}})();
  let state = {...defaultState(),...(stored && typeof stored === 'object' ? stored : {})};
  let ui = {route:'home',lessonId:'hello',stage:'discover',questionIndex:0,selected:null,checked:false,answers:{}};
  let openPhrases = [];
  let mediaRecorder = null;
  let mediaStream = null;
  let recording = false;
  let recordedURL = null;
  let toastTimeout;

  function save(){try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{notify('Browser storage is unavailable; progress may not persist.');}}
  function notify(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('show'),3000);}
  function icon(name){const icons={arrow:'→',check:'✓',listen:'♫',back:'←',clock:'◷',book:'▤',teacher:'◉',source:'↗',record:'●',stop:'■'};return icons[name]||name;}
  function progress(){return Math.round(100*state.completed.length/Math.max(lessons.length,1));}
  function nextLesson(){return lessons.find(l=>!state.completed.includes(l.id))||lessons[0];}
  function currentLesson(){return lessons.find(l=>l.id===ui.lessonId)||lessons[0];}
  function sourceNote(id){return `<a href="https://tatoeba.org/en/sentences/show/${id}" target="_blank" rel="noopener noreferrer">Tatoeba CC0 · sentence #${id} ↗</a>`;}
  function resetLessonUI(id){ui.lessonId=id;ui.stage='discover';ui.questionIndex=0;ui.selected=null;ui.checked=false;ui.answers={};}
  function routeFromHash(){const hash=decodeURIComponent(location.hash.replace(/^#/,''));if(hash.startsWith('lesson/')){const id=hash.slice(7);if(lessons.some(l=>l.id===id)){ui.route='lesson';if(ui.lessonId!==id)resetLessonUI(id);return;}}ui.route=['home','student','teacher','sources'].includes(hash)?hash:'home';}
  function navigate(route,id){const target=route==='lesson'?`lesson/${id}`:route;if(location.hash.slice(1)===target){if(route==='lesson'&&ui.lessonId!==id)resetLessonUI(id);ui.route=route;render();}else{location.hash=target;}window.scrollTo({top:0,behavior:'instant'});}
  function navButton(route,label){const selected=(route==='student'&&(ui.route==='student'||ui.route==='lesson'))||ui.route===route;return `<button type="button" class="nav-btn ${selected?'active':''}" data-route="${route}">${label}</button>`;}
  function renderShell(content){
    const isTeacher=ui.route==='teacher';
    root.innerHTML=`<div class="top-notice"><span>Interactive concept preview</span> Sample learners · Local progress · No real accounts</div>
      <header class="site-header"><div class="head-inner"><a class="brand" href="#home" aria-label="AmberTheory German Studio home"><span class="brand-mark">At</span><span class="brand-text"><span class="brand-name">AmberTheory</span><span class="brand-sub">German Studio</span></span></a>
      <nav class="primary-nav" aria-label="Main navigation">${navButton('home','Overview')}${navButton('student','My learning')}${navButton('teacher','Teacher studio')}${navButton('sources','Sources')}</nav>
      <div class="role-toggle" aria-label="Demo role switch"><button type="button" data-role="student" class="${!isTeacher?'active':''}">Student</button><button type="button" data-role="teacher" class="${isTeacher?'active':''}">Teacher</button></div></div></header>
      <nav class="mobile-nav" aria-label="Mobile navigation"><button type="button" data-route="home" class="${ui.route==='home'?'active':''}"><span>⌂</span>Home</button><button type="button" data-route="student" class="${ui.route==='student'||ui.route==='lesson'?'active':''}"><span>▤</span>Learn</button><button type="button" data-route="teacher" class="${isTeacher?'active':''}"><span>◎</span>Teach</button><button type="button" data-route="sources" class="${ui.route==='sources'?'active':''}"><span>↗</span>Sources</button></nav>
      <main class="shell page">${content}</main><footer class="footer"><div class="shell footer-inner"><span>AmberTheory · German Studio concept · Teacher-led learning</span><div class="footer-links"><a href="#sources">Open materials & credits</a><a href="https://www.coe.int/en/web/common-european-framework-reference-languages" target="_blank" rel="noopener noreferrer">CEFR reference ↗</a><span>Demo only · No real accounts</span></div></div></footer>`;
  }
  function render(){routeFromHash();let page='';if(ui.route==='student')page=renderStudent();else if(ui.route==='lesson')page=renderLesson();else if(ui.route==='teacher')page=renderTeacher();else if(ui.route==='sources')page=renderSources();else page=renderHome();renderShell(page);}

  function renderHome(){
    const next=nextLesson();
    return `<section class="hero"><div class="hero-copy"><span class="eyebrow">A new way to learn together</span><h1>Learn German.<br/><em>Find your voice.</em></h1><p class="lead">A considered place to discover the language, practise between classes and grow with guidance from a real teacher.</p><div class="hero-actions"><button class="btn btn-primary" data-lesson="${next.id}">Try the first lesson ${icon('arrow')}</button><button class="btn btn-outline" data-route="teacher">Explore teacher view</button></div><div class="hero-foot"><span><b></b> Beginner-friendly</span><span><b></b> Interactive practice</span><span><b></b> Human feedback</span></div></div><div class="hero-art" aria-hidden="true"><div class="sun"></div><div class="arch"></div><div class="street-line"></div><svg class="squiggle" viewBox="0 0 500 440" preserveAspectRatio="none"><path d="M37 343 C 95 234, 147 359, 192 243 S 320 104, 439 190"/></svg><div class="bubble bubble-a">Hallo!<span>Hello</span></div><div class="bubble bubble-b">Wie geht's?<span>How are you?</span></div></div></section>
    <div class="stat-row"><div class="stat card"><div class="stat-icon">◌</div><div><strong>A1</strong><p>Beginner pathway</p></div></div><div class="stat card"><div class="stat-icon">▤</div><div><strong>${lessons.length}</strong><p>Complete sample lessons</p></div></div><div class="stat card"><div class="stat-icon">◎</div><div><strong>2 views</strong><p>Student and teacher</p></div></div></div>
    <section><div class="section-intro"><div><span class="eyebrow">Your learning path</span><h2>Start with real conversations</h2><p>Original A1 demo lessons created for this prototype. Your teacher will validate and refine the complete curriculum.</p></div><button class="view-link" data-route="student">My learning dashboard ${icon('arrow')}</button></div><div class="lesson-grid">${lessons.map(lessonCard).join('')}</div></section>
    <section><div class="section-intro"><div><span class="eyebrow">One shared experience</span><h2>Learning meets guidance</h2></div></div><div class="split-feature"><article class="feature green"><span class="feature-icon">▤</span><h3>A student’s own rhythm</h3><p>Short lessons, everyday dialogue, practice checks and a personal path back to what matters.</p><button class="btn btn-white btn-small" data-route="student">See student dashboard ${icon('arrow')}</button></article><article class="feature cream"><span class="feature-icon">◎</span><h3>A teacher’s perspective</h3><p>See practice results, review written work, guide a cohort and make every class more personal.</p><button class="btn btn-primary btn-small" data-route="teacher">See teacher studio ${icon('arrow')}</button></article></div></section>`;
  }
  function lessonCard(l){const done=state.completed.includes(l.id);return `<article class="lesson-card card"><div class="lesson-head"><span class="lesson-number">LESSON ${l.unit} / A1</span><span class="tag ${done?'tag-dark':'tag-muted'}">${done?'✓ Completed':escape(l.duration)}</span></div><div><h3>${escape(l.title)}</h3><p>${escape(l.subtitle)}</p></div><div class="mini-phrase">${escape(l.phrase.de.split('.')[0])}</div><button class="view-link" data-lesson="${l.id}">${done?'Revisit lesson':'Open lesson'} ${icon('arrow')}</button></article>`;}

  function renderStudent(){
    const next=nextLesson();const pts=progress();const assignments=state.assigned;
    const skills=[['Listening',30],['Speaking',20],['Reading',35],['Writing',25]].map(([name,base])=>{const value=Math.min(100,base+Math.round(pts*.55));return `<div class="card skill"><div class="skill-top"><span>${name}</span><span class="tag tag-muted">A1 demo</span></div><strong>${value}%</strong><div class="progress-shell"><div class="progress-fill" style="width:${value}%"></div></div></div>`;}).join('');
    return `<div class="dash-header"><div><span class="eyebrow">Your learning space</span><h1>Guten Tag, learner.</h1><p class="lead">A little progress every day becomes a language you can use. Pick up where you left off.</p></div><span class="tag tag-warm">Demo learner · Local browser</span></div>
    <div class="dash-grid"><section class="learning-panel"><span class="tag tag-dark">A1 · Beginner German</span><h2>Make the next conversation yours.</h2><p>${pts===100?'All sample lessons completed. Revisit a lesson or try a different example.':'Your path is ready. Listen, understand, check your knowledge and try saying it yourself.'}</p><div class="progress-shell"><div class="progress-fill" style="width:${pts}%"></div></div><div class="minor-progress"><span>${state.completed.length} of ${lessons.length} lessons finished</span><span>${pts}%</span></div><button class="btn btn-white" data-lesson="${next.id}">${pts===100?'Revisit lessons':'Continue learning'} ${icon('arrow')}</button></section><section class="card card-pad"><div class="lesson-head"><h3>Your next steps</h3><span class="tag tag-muted">A1</span></div><p class="subtle" style="font-size:12px;margin:8px 0 19px">Small, useful steps towards confident conversations.</p><div class="next-list">${lessons.slice(0,4).map((l,i)=>`<div class="next-item"><span class="next-dot">${state.completed.includes(l.id)?'✓':i+1}</span><div><strong>${escape(l.title)}</strong><p>${escape(l.duration)} · ${escape(l.skill)}</p></div><button class="btn btn-ghost btn-small" data-lesson="${l.id}">Open →</button></div>`).join('')}</div></section></div>
    <div class="assignment-strip"><div><span class="upper">Teacher assignment</span><h3 style="margin-top:6px">${assignments?'Introduce yourself in two sentences':'No active assignment'}</h3><p>${assignments?'Practise the first lesson, write your introduction and send it for demo teacher feedback.':'Your teacher can assign a writing task from the Teacher Studio view.'}</p></div><button class="btn btn-primary" data-lesson="hello">${assignments?'Start assignment':'Practise anyway'} ${icon('arrow')}</button></div>
    ${state.submissions.length?`<section class="card card-pad" style="margin-top:18px"><div class="lesson-head"><h3>Teacher feedback</h3><span class="tag tag-muted">Your submitted work</span></div><div class="queue" style="margin-top:17px">${state.submissions.slice(0,4).map(s=>`<div class="queue-item"><div class="queue-head"><strong>${escape(lessons.find(l=>l.id===s.lessonId)?.title||'Practice')}</strong><span class="tag ${state.reviews[s.id]?'tag-dark':'tag-warm'}">${state.reviews[s.id]?'Reviewed':'Awaiting review'}</span></div><blockquote>${escape(s.text)}</blockquote>${state.reviews[s.id]?`<div class="feedback"><b>From your teacher:</b> ${escape(state.reviews[s.id].note)}</div>`:'<p>A teacher can respond in the Teacher Studio demo.</p>'}</div>`).join('')}</div></section>`:''}
    <section><div class="section-intro"><div><span class="eyebrow">Sample skill picture</span><h2>Four ways to grow</h2><p>Illustrative skill indicators for the concept; these are not measured proficiency scores.</p></div></div><div class="skill-grid">${skills}</div></section>
    <section><div class="section-intro"><div><span class="eyebrow">Course outline</span><h2>Your A1 sample lessons</h2></div></div><div class="lesson-grid">${lessons.map(lessonCard).join('')}</div></section>`;
  }

  function sidebar(){return `<aside class="course-sidebar card" aria-label="Lesson outline"><div class="sidebar-overline">Course outline</div><div class="sidebar-title">German A1</div>${lessons.map(l=>`<button class="sidebar-lesson ${l.id===ui.lessonId?'active':''} ${state.completed.includes(l.id)?'done':''}" data-lesson="${l.id}"><span class="count">${state.completed.includes(l.id)?'✓':l.unit}</span><span><b>${escape(l.title)}</b><small>${escape(l.duration)} · ${escape(l.skill)}</small></span></button>`).join('')}</aside>`;}
  const stageNames=[['discover','01 · Discover'],['understand','02 · Understand'],['check','03 · Check'],['apply','04 · Use it']];
  function renderLesson(){const l=currentLesson();if(!l)return '<p>No lessons available.</p>';const stage=stageNames.find(x=>x[0]===ui.stage)||stageNames[0];const done=state.completed.includes(l.id);
    return `<div class="course-layout">${sidebar()}<div class="lesson-main"><div class="lesson-banner"><div><span class="eyebrow">German A1 · Lesson ${l.unit}</span><h1>${escape(l.title)}</h1><p>${escape(l.subtitle)}</p></div><span class="tag ${done?'tag-dark':'tag-warm'}">${done?'✓ Completed':escape(l.duration)}</span></div><nav class="lesson-stage" aria-label="Lesson stages">${stageNames.map(([id,label])=>`<button class="stage-tab ${id===ui.stage?'active':''}" data-stage="${id}">${label}</button>`).join('')}</nav><article class="lesson-body card"><span class="eyebrow">${escape(stage[1])}</span>${renderStage(l)}</article><div class="lesson-nav"><button data-route="student">← My learning</button><button data-lesson="${lessons[(lessons.indexOf(l)+1)%lessons.length].id}">Next lesson →</button></div></div></div>`;
  }
  function renderStage(l){
    if(ui.stage==='discover')return `<h2>A moment from everyday life</h2><p class="explain">${escape(l.scene)}</p><div class="phrase-panel"><div><div class="upper">Hear the language</div><div class="phrase-de">${escape(l.phrase.de)}</div><div class="phrase-en">${escape(l.phrase.en)}</div>${l.phrase.sourceId?`<div class="phrase-source">${sourceNote(l.phrase.sourceId)}</div>`:''}</div><button class="sound-button" data-speak="${escape(l.phrase.de)}" aria-label="Play German pronunciation" title="Play browser German voice">♫</button></div><div class="study-note"><b>Listen and repeat.</b> Use the sound button to hear a German browser voice, then say the phrase aloud. Voice quality depends on the voices installed on your device.</div><div class="stage-foot"><p>Try to hear the rhythm before focusing on every word.</p><button class="btn btn-primary" data-stage="understand">Understand the words ${icon('arrow')}</button></div>`;
    if(ui.stage==='understand')return `<h2>Understand it, word by word</h2><p class="explain">${l.pattern}</p><div class="word-list">${l.words.map(([de,en])=>`<div class="word"><b>${escape(de)}</b><p>${escape(en)}</p><button class="view-link" data-speak="${escape(de)}" aria-label="Hear ${escape(de)}" style="font-size:11px;margin-top:7px">♫ Listen</button></div>`).join('')}</div><div class="tip"><b>Pronunciation and usage tip:</b> ${escape(l.tip)}</div><div class="dialogue">${l.dialogue.map(([name,de,en])=>`<div class="speech"><span>${escape(name)}</span><strong>${escape(de)}</strong><div class="muted" style="font-size:11px;margin-top:5px">${escape(en)}</div></div>`).join('')}</div><div class="stage-foot"><button class="btn btn-outline" data-stage="discover">← Back</button><button class="btn btn-primary" data-stage="check">Check understanding ${icon('arrow')}</button></div>`;
    if(ui.stage==='check')return renderQuiz(l);
    return renderApply(l);
  }
  function renderQuiz(l){
    if(ui.questionIndex>=l.questions.length){const score=Object.values(ui.answers).filter(a=>a.correct).length;return `<div class="finish-panel"><span class="tag tag-dark">Practice completed</span><div class="finish-score">${score}/${l.questions.length}</div><h2>Good work — keep practising.</h2><p>Your score reflects these sample questions, not a certified language level. Review the explanation of anything you missed.</p><button class="btn btn-primary" data-stage="apply">Use it in a real sentence ${icon('arrow')}</button><button class="btn btn-ghost" data-retake style="margin-top:20px">Retake quiz</button></div>`;}
    const q=l.questions[ui.questionIndex];const answer=ui.answers[ui.questionIndex];const checked=ui.checked;return `<div class="quiz-counter">QUESTION ${ui.questionIndex+1} OF ${l.questions.length}</div><h2 style="margin-top:17px">${escape(q.q)}</h2><p>Choose an answer, check it and see why it works.</p><div class="choice-list">${q.options.map((opt,i)=>`<button class="choice ${ui.selected===i?'selected':''} ${checked&&i===q.correct?'correct':''} ${checked&&ui.selected===i&&i!==q.correct?'incorrect':''}" data-choice="${i}" ${checked?'disabled':''}>${escape(opt)}</button>`).join('')}</div>${checked?`<div class="feedback ${answer?.correct?'':'error'}"><b>${answer?.correct?'Correct!':'Not quite.'}</b> ${escape(q.why)}</div>`:''}<div class="stage-foot"><button class="btn btn-outline" data-stage="understand">← Review lesson</button>${checked?`<button class="btn btn-primary" data-next-question>${ui.questionIndex+1===l.questions.length?'See my result':'Next question'} ${icon('arrow')}</button>`:`<button class="btn btn-primary" data-check-answer ${ui.selected===null?'disabled':''}>Check answer ${icon('arrow')}</button>`}</div>`;
  }
  function renderApply(l){const draft=state.drafts[l.id]||'';const hasSubmission=state.submissions.some(s=>s.lessonId===l.id);const ready=ui.questionIndex>=l.questions.length;return `<h2>Your turn to use German</h2><p class="explain">Learning becomes useful when you form your own sentences. Write a response now and then try speaking it aloud.</p><div class="task-card"><strong>Teacher practice task</strong><p>${escape(l.apply)}</p><div class="study-note" style="margin-top:12px">Example: <b>${escape(l.sample)}</b></div></div><label class="form-field" for="student-response">Write your German response</label><textarea class="text-entry" id="student-response" data-draft="${l.id}" maxlength="600" placeholder="Schreiben Sie auf Deutsch …">${escape(draft)}</textarea><div class="stage-foot"><p>Saved locally in this browser. Your teacher can view it in this demonstration.</p><button class="btn btn-copper" data-submit-response="${l.id}" ${draft.trim().length<5?'disabled':''}>Send for teacher feedback ${icon('arrow')}</button></div>${hasSubmission?'<div class="status-success">✓ A written response from this lesson appears in the Teacher Studio review queue.</div>':''}<div class="recorder"><button class="btn btn-outline btn-small" data-record>${recording?'■ Stop recording':'● Record speaking'}</button>${recordedURL?`<audio controls src="${recordedURL}"></audio>`:'<span class="muted">Optional microphone practice stays on this device. It is not sent to your teacher.</span>'}</div><div class="stage-foot"><button class="btn btn-outline" data-stage="check">← Review quiz</button><button class="btn btn-primary" data-finish-lesson="${l.id}">${ready?'Finish lesson':'Complete quiz to finish'} ${icon('arrow')}</button></div>`;}

  function renderTeacher(){
    const demoStudents=[
      {name:'Aarav M.',initials:'AM',level:'A1',progress:80,score:86,status:'On track'},
      {name:'Meera K.',initials:'MK',level:'A1',progress:60,score:72,status:'On track'},
      {name:'Rhea S.',initials:'RS',level:'A1',progress:40,score:64,status:'Needs review'},
      {name:'Sahil D.',initials:'SD',level:'A1',progress:70,score:81,status:'On track'},
      {name:'Demo learner',initials:'DL',level:'A1',progress:progress(),score:Math.round(Object.values(state.scores).reduce((a,b)=>a+b,0)/Math.max(Object.keys(state.scores).length,1)),status:state.submissions.some(s=>!state.reviews[s.id])?'Awaiting review':'Practising'}
    ];
    const seeded=[{id:'seed-rhea',name:'Rhea S.',lessonId:'hello',text:'Hallo, ich heiße Rhea. Ich komme aus Indien.',sample:true},{id:'seed-sahil',name:'Sahil D.',lessonId:'cafe',text:'Ich möchte einen Kaffee, bitte.',sample:true}];
    const submissions=[...state.submissions.map(s=>({id:s.id,name:'Demo learner',lessonId:s.lessonId,text:s.text,sample:false})),...seeded];
    const pending=submissions.filter(s=>!state.reviews[s.id]);
    return `<div class="dash-header"><div><span class="eyebrow">Your teaching workspace</span><h1>Guide every learner.</h1><p class="lead">A preview of how a teacher can follow progress, review practice and keep a small cohort moving together.</p></div><span class="tag tag-warm">Sample cohort · Not live data</span></div>
    <div class="teacher-stats"><div class="card teacher-stat"><span class="upper">Learners in cohort</span><strong>5</strong><p>4 fictional + current demo</p></div><div class="card teacher-stat"><span class="upper">Average completion</span><strong>${Math.round(demoStudents.reduce((a,s)=>a+s.progress,0)/demoStudents.length)}%</strong><p>Illustrative sample view</p></div><div class="card teacher-stat"><span class="upper">To review</span><strong>${pending.length}</strong><p>Written exercises</p></div><div class="card teacher-stat"><span class="upper">Active pathway</span><strong>A1</strong><p>${lessons.length} sample lessons</p></div></div>
    <div class="teacher-grid"><section class="card teacher-panel"><h3>My beginner cohort</h3><p class="subtitle">Fictional example students demonstrate the layout. Only the Demo learner changes as you practise.</p><div class="table-wrap"><table class="roster"><thead><tr><th>Learner</th><th>Level</th><th>Course progress</th><th>Practice</th><th>Support</th></tr></thead><tbody>${demoStudents.map(s=>`<tr><td class="student-name"><span class="avatar">${s.initials}</span>${escape(s.name)}</td><td>${s.level}</td><td><div class="bar-inline"><div class="progress-shell"><div class="progress-fill" style="width:${s.progress}%"></div></div><span>${s.progress}%</span></div></td><td>${s.score}%</td><td><span class="tag ${s.status==='Needs review'?'tag-warm':'tag-muted'}">${escape(s.status)}</span></td></tr>`).join('')}</tbody></table></div><div class="demo-warning">These names and historical results are fictional examples. This static prototype does not yet enrol real students or synchronise progress between devices.</div></section>
    <section class="card teacher-panel"><div class="lesson-head"><h3>Practice to review</h3><span class="tag tag-warm">${pending.length} waiting</span></div><p class="subtitle">Open submissions, provide feedback and mark the review complete.</p><div class="queue">${pending.length?pending.map(s=>`<article class="queue-item"><div class="queue-head"><strong>${escape(s.name)}</strong><span class="tag ${s.sample?'tag-muted':'tag-dark'}">${s.sample?'Seed sample':'From this browser'}</span></div><p>${escape(lessons.find(l=>l.id===s.lessonId)?.title||'German practice')}</p><blockquote>${escape(s.text)}</blockquote><label class="form-field" for="fb-${s.id}" style="margin-top:10px">Your feedback</label><textarea id="fb-${s.id}" data-feedback="${s.id}" class="text-entry" placeholder="A short, useful note for this learner…"></textarea><button class="btn btn-primary btn-small" data-review="${s.id}">Save feedback & mark reviewed</button></article>`).join(''):'<div class="empty">Everything reviewed. Try submitting a response in Student view.</div>'}</div></section></div>
    <div class="teacher-prompt"><span class="eyebrow">Class activity</span><h3 style="font-size:25px;margin-top:8px">Assign a short introduction</h3><p>Send the first speaking-and-writing prompt to your Demo learner. This toggles an activity inside this browser; it does not notify real students.</p><button class="btn btn-primary btn-small" data-assignment="${state.assigned?'off':'on'}">${state.assigned?'Remove demo assignment':'Assign to demo learner'}</button><button class="btn btn-outline btn-small" data-role="student">Switch to student view</button></div>
    <section><div class="section-intro"><div><span class="eyebrow">Course stewardship</span><h2>Teacher-approved curriculum</h2><p>In a real rollout, content goes through expert review before students see it. Here you can inspect each original sample lesson.</p></div></div><div class="lesson-grid">${lessons.map(lessonCard).join('')}</div></section>`;
  }

  function renderSources(){const defaultPhrases=[{id:8246323,german:'Ich nehme bitte ein Wiener Schnitzel.',english:'I’ll have a Wiener schnitzel, please.'},{id:8981453,german:'Nach vorne!',english:'Forward!'},{id:7047540,german:'Wollen Sie zusammen spazieren gehen?',english:'Would you like to go for a walk together?'},{id:8969693,german:'Das Leben ist wunderschön!',english:'Life is wonderful!'},{id:9280790,german:'Was für ein Glück!',english:'What luck!'}];const phrases=openPhrases.length?openPhrases:defaultPhrases;
    return `<div class="source-intro"><span class="eyebrow">Transparent foundations</span><h1 style="margin:12px 0 17px">Open material, clear sources.</h1><p class="lead">The experience is built around original teaching examples and a small hand-picked collection of public-domain German sentences. The course will need a German teacher's review before use with learners.</p></div>
    <div class="source-cards"><article class="source-card card"><span class="tag tag-dark">Open-data examples</span><h3>Tatoeba German CC0 sentences</h3><p>Five German sentences from the CC0 export, selected for an introductory phrase library. English glosses and teaching notes are original; no audio has been copied. You can inspect each original sentence and its ID.</p><p style="margin-top:16px"><a href="https://downloads.tatoeba.org/exports/per_language/deu/deu_sentences_CC0.tsv.bz2" target="_blank" rel="noopener noreferrer">See CC0 dataset ↗</a></p></article><article class="source-card card"><span class="tag tag-warm">Framework references</span><h3>CEFR & Goethe preparation</h3><p>We use CEFR A1 as the learning reference and link to Goethe-Institut's official exam practice page. Their protected materials are not copied into this demo.</p><p style="margin-top:16px"><a href="https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale" target="_blank" rel="noopener noreferrer">CEFR framework ↗</a> &nbsp;·&nbsp; <a href="https://www.goethe.de/ins/de/en/prf/exc.html" target="_blank" rel="noopener noreferrer">Goethe practice ↗</a></p></article></div>
    <section><div class="section-intro"><div><span class="eyebrow">Mini phrase library</span><h2>Learn from open sentences</h2><p>Pronunciation is generated by the browser, not copied from a source recording.</p></div></div><div class="source-list">${phrases.map(p=>`<div class="source-entry"><div><strong>${escape(p.german)}</strong><p>${escape(p.english)}</p></div><div style="display:flex;gap:9px;align-items:center"><button class="sound-button" style="height:38px;width:38px;font-size:17px" data-speak="${escape(p.german)}" aria-label="Hear German sentence">♫</button><a href="https://tatoeba.org/en/sentences/show/${p.id}" target="_blank" rel="noopener noreferrer">Source #${p.id} ↗</a></div></div>`).join('')}</div></section><div class="demo-warning"><b>Copyright and quality:</b> Purchased textbooks and publisher recordings are not included. Publication and digital copying require checking the publisher's rights. A teacher must review grammar, translations, phonetics and placement before releasing the content to students.</div><button class="btn btn-outline btn-small" data-reset style="margin-top:21px">Reset demo progress on this device</button>`;
  }

  function speak(text){if(!('speechSynthesis' in window)){notify('Audio pronunciation is unavailable in this browser.');return;}const utterance=new SpeechSynthesisUtterance(text);utterance.lang='de-DE';utterance.rate=.83;const germanVoice=window.speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith('de'));if(germanVoice)utterance.voice=germanVoice;window.speechSynthesis.cancel();window.speechSynthesis.speak(utterance);}
  async function toggleRecording(){
    if(recording&&mediaRecorder){mediaRecorder.stop();recording=false;notify('Recording complete. Play it back below.');return;}
    if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){notify('Microphone recording is unavailable here.');return;}
    try{mediaStream=await navigator.mediaDevices.getUserMedia({audio:true});const chunks=[];mediaRecorder=new MediaRecorder(mediaStream);mediaRecorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};mediaRecorder.onstop=()=>{if(recordedURL)URL.revokeObjectURL(recordedURL);recordedURL=URL.createObjectURL(new Blob(chunks,{type:mediaRecorder.mimeType||'audio/webm'}));mediaStream?.getTracks().forEach(t=>t.stop());mediaStream=null;render();};mediaRecorder.start();recording=true;render();notify('Recording locally — click stop when ready.');}catch{notify('Microphone access was declined or unavailable.');}
  }
  function handleAction(target){
    const button=target.closest('button');if(!button||button.disabled)return;
    if(button.hasAttribute('data-route'))return navigate(button.dataset.route);
    if(button.hasAttribute('data-role'))return navigate(button.dataset.role==='teacher'?'teacher':'student');
    if(button.hasAttribute('data-lesson')){if(ui.lessonId!==button.dataset.lesson)resetLessonUI(button.dataset.lesson);return navigate('lesson',button.dataset.lesson);}
    if(button.hasAttribute('data-stage')){ui.stage=button.dataset.stage;render();return;}
    if(button.hasAttribute('data-speak'))return speak(button.dataset.speak);
    if(button.hasAttribute('data-choice')){if(!ui.checked){ui.selected=Number(button.dataset.choice);render();}return;}
    if(button.hasAttribute('data-check-answer')){const l=currentLesson();const q=l.questions[ui.questionIndex];if(ui.selected===null)return;ui.answers[ui.questionIndex]={chosen:ui.selected,correct:ui.selected===q.correct};ui.checked=true;render();return;}
    if(button.hasAttribute('data-next-question')){ui.questionIndex++;ui.selected=null;ui.checked=false;render();return;}
    if(button.hasAttribute('data-retake')){ui.questionIndex=0;ui.selected=null;ui.checked=false;ui.answers={};render();return;}
    if(button.hasAttribute('data-submit-response')){const id=button.dataset.submitResponse;const draft=(state.drafts[id]||'').trim();if(draft.length<5){notify('Write a sentence before submitting.');return;}state.submissions.unshift({id:`entry-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,lessonId:id,text:draft});save();notify('Response added to the demo teacher queue.');render();return;}
    if(button.hasAttribute('data-finish-lesson')){const l=currentLesson();if(Object.keys(ui.answers).length<l.questions.length){ui.stage='check';notify('Complete the three practice questions to finish.');render();return;}if(!state.completed.includes(l.id))state.completed.push(l.id);state.scores[l.id]=Math.round(100*Object.values(ui.answers).filter(x=>x.correct).length/l.questions.length);save();notify('Lesson progress saved on this device.');navigate('student');return;}
    if(button.hasAttribute('data-record')){toggleRecording();return;}
    if(button.hasAttribute('data-review')){const id=button.dataset.review;const note=(document.querySelector(`[data-feedback="${CSS.escape(id)}"]`)?.value||'').trim();if(note.length<5){notify('Write a short feedback note first.');return;}state.reviews[id]={note,at:new Date().toISOString()};save();notify('Review saved in this browser.');render();return;}
    if(button.hasAttribute('data-assignment')){state.assigned=button.dataset.assignment==='on';save();notify(state.assigned?'Assignment is visible to the demo learner.':'Demo assignment removed.');render();return;}
    if(button.hasAttribute('data-reset')){if(confirm('Clear lesson progress and local demo reviews from this browser?')){state=defaultState();save();resetLessonUI('hello');navigate('home');notify('Demo reset.');}return;}
  }
  root.addEventListener('click',e=>handleAction(e.target));
  root.addEventListener('input',e=>{if(e.target.matches('[data-draft]')){const id=e.target.dataset.draft;state.drafts[id]=e.target.value;save();const submit=document.querySelector('[data-submit-response]');if(submit)submit.disabled=e.target.value.trim().length<5;}});
  window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});});
  window.addEventListener('beforeunload',()=>{if(recordedURL)URL.revokeObjectURL(recordedURL);mediaStream?.getTracks().forEach(t=>t.stop());});
  fetch('./data/tatoeba-cc0.json').then(r=>r.ok?r.json():null).then(data=>{if(data&&Array.isArray(data.sentences)){openPhrases=data.sentences;if(ui.route==='sources')render();}}).catch(()=>{});
  render();
})();
